14	/// Complete the given command, shell-agnostic
15	pub fn complete(
16	    cmd: &mut clap::Command,
17	    args: Vec<OsString>,
18	    arg_index: usize,
19	    current_dir: Option<&std::path::Path>,
20	) -> Result<Vec<CompletionCandidate>, std::io::Error> {
21	    debug!("complete: args={args:?}, arg_index={arg_index:?}, current_dir={current_dir:?}");
22	    cmd.build();
23	
24	    let raw_args = clap_lex::RawArgs::new(args);
25	    let mut cursor = raw_args.cursor();
26	    let mut target_cursor = raw_args.cursor();
27	    raw_args.seek(
28	        &mut target_cursor,
29	        clap_lex::SeekFrom::Start(arg_index as u64),
30	    );
31	    // As we loop, `cursor` will always be pointing to the next item
32	    raw_args.next_os(&mut target_cursor);
33	    debug!("complete: target_cursor={target_cursor:?}");
34	
35	    // TODO: Multicall support
36	    if !cmd.is_no_binary_name_set() {
37	        raw_args.next_os(&mut cursor);
38	    }
39	
40	    let mut current_cmd = &*cmd;
41	    let mut pos_index = 1;
42	    let mut is_escaped = false;
43	    let mut next_state = ParseState::ValueDone;
44	    while let Some(arg) = raw_args.next(&mut cursor) {
45	        let current_state = next_state;
46	        next_state = ParseState::ValueDone;
47	        debug!(
48	            "complete::next: arg={:?}, current_state={current_state:?}, cursor={cursor:?}",
49	            arg.to_value_os(),
50	        );
51	        if cursor == target_cursor {
52	            return complete_arg(
53	                &arg,
54	                current_cmd,
55	                current_dir,
56	                pos_index,
57	                is_escaped,
58	                current_state,
59	            );
60	        }
61	
62	        if let Ok(value) = arg.to_value() {
63	            if let Some(next_cmd) = current_cmd.find_subcommand(value) {
64	                current_cmd = next_cmd;
65	                pos_index = 1;
66	                continue;
67	            }
68	        }
69	
70	        if is_escaped {
71	            (next_state, pos_index) =
72	                parse_positional(current_cmd, pos_index, is_escaped, current_state);
73	        } else if arg.is_escape() {
74	            is_escaped = true;
75	        } else if opt_allows_hyphen(&current_state, &arg) {
76	            match current_state {
77	                ParseState::Opt((opt, count)) => next_state = parse_opt_value(opt, count),
78	                _ => unreachable!("else branch is only reachable in Opt state"),
79	            }
80	        } else if let Some((flag, value)) = arg.to_long() {
81	            if let Ok(flag) = flag {
82	                let opt = current_cmd.get_arguments().find(|a| {
83	                    let longs = a.get_long_and_visible_aliases();
84	                    let is_find = longs.map(|v| {
85	                        let mut iter = v.into_iter();
86	                        let s = iter.find(|s| *s == flag);
87	                        s.is_some()
88	                    });
89	                    is_find.unwrap_or(false)
90	                });
91	
92	                if let Some(opt) = opt {
93	                    if opt.get_num_args().expect("built").takes_values() && value.is_none() {
94	                        next_state = ParseState::Opt((opt, 1));
95	                    };
96	                } else if pos_allows_hyphen(current_cmd, pos_index) {
97	                    (next_state, pos_index) =
98	                        parse_positional(current_cmd, pos_index, is_escaped, current_state);
99	                }
100	            }
101	        } else if let Some(short) = arg.to_short() {
102	            let (_, takes_value_opt, mut short) = parse_shortflags(current_cmd, short);
103	            if let Some(opt) = takes_value_opt {
104	                if short.next_value_os().is_none() {
105	                    next_state = ParseState::Opt((opt, 1));
106	                }
107	            } else if pos_allows_hyphen(current_cmd, pos_index) {
108	                (next_state, pos_index) =
109	                    parse_positional(current_cmd, pos_index, is_escaped, current_state);
110	            }
111	        } else {
112	            match current_state {
113	                ParseState::ValueDone | ParseState::Pos(..) => {
114	                    (next_state, pos_index) =
115	                        parse_positional(current_cmd, pos_index, is_escaped, current_state);
116	                }
117	                ParseState::Opt((opt, count)) => next_state = parse_opt_value(opt, count),
118	            }
119	        }
120	    }
121	
122	    Err(std::io::Error::other("no completion generated"))
123	}
