137	fn complete_arg(
138	    arg: &clap_lex::ParsedArg<'_>,
139	    cmd: &clap::Command,
140	    current_dir: Option<&std::path::Path>,
141	    pos_index: usize,
142	    is_escaped: bool,
143	    state: ParseState<'_>,
144	) -> Result<Vec<CompletionCandidate>, std::io::Error> {
145	    debug!(
146	        "complete_arg: arg={:?}, cmd={:?}, current_dir={:?}, pos_index={:?}, state={:?}",
147	        arg,
148	        cmd.get_name(),
149	        current_dir,
150	        pos_index,
151	        state
152	    );
153	    let mut completions = Vec::<CompletionCandidate>::new();
154	
155	    match state {
156	        ParseState::ValueDone => {
157	            if let Ok(value) = arg.to_value() {
158	                completions.extend(complete_subcommand(value, cmd));
159	            }
160	
161	            if let Some(positional) = cmd
162	                .get_positionals()
163	                .find(|p| p.get_index() == Some(pos_index))
164	            {
165	                completions.extend(complete_arg_value(
166	                    arg.to_value(),
167	                    positional,
168	                    current_dir,
169	                    0,
170	                ));
171	            }
172	            if !is_escaped {
173	                completions.extend(complete_option(arg, cmd, current_dir));
174	            }
175	        }
176	        ParseState::Pos((_, num_arg)) => {
177	            if let Some(positional) = cmd
178	                .get_positionals()
179	                .find(|p| p.get_index() == Some(pos_index))
180	            {
181	                completions.extend(complete_arg_value(
182	                    arg.to_value(),
183	                    positional,
184	                    current_dir,
185	                    num_arg.saturating_sub(1),
186	                ));
187	                if !is_escaped
188	                    && positional
189	                        .get_num_args()
190	                        .is_some_and(|num_args| num_arg >= num_args.min_values())
191	                {
192	                    completions.extend(complete_option(arg, cmd, current_dir));
193	                }
194	            }
195	        }
196	        ParseState::Opt((opt, count)) => {
197	            completions.extend(complete_arg_value(
198	                arg.to_value(),
199	                opt,
200	                current_dir,
201	                count.saturating_sub(1),
202	            ));
203	            let min = opt.get_num_args().map(|r| r.min_values()).unwrap_or(0);
204	            if count > min {
205	                // Also complete this raw_arg as a positional argument, flags, options and subcommand.
206	                completions.extend(complete_arg(
207	                    arg,
208	                    cmd,
209	                    current_dir,
210	                    pos_index,
211	                    is_escaped,
212	                    ParseState::ValueDone,
213	                )?);
214	            }
215	        }
216	    }
217	    if completions.iter().any(|a| !a.is_hide_set()) {
218	        completions.retain(|a| !a.is_hide_set());
219	    }
220	    let mut seen_ids = std::collections::HashSet::new();
221	    completions.retain(move |a| {
222	        if let Some(id) = a.get_id().cloned() {
223	            seen_ids.insert(id)
224	        } else {
225	            true
226	        }
227	    });
228	
229	    let mut tags = Vec::new();
230	    for candidate in &completions {
231	        let tag = candidate.get_tag().cloned();
232	        if !tags.contains(&tag) {
233	            tags.push(tag);
234	        }
235	    }
236	    completions.sort_by_key(|c| {
237	        (
238	            tags.iter().position(|t| c.get_tag() == t.as_ref()),
239	            c.get_display_order(),
240	        )
241	    });
242	
243	    Ok(completions)
244	}
